// rot12 is a butterfly rotation: Round2(x*c - y*s, 12), Round2(x*s + y*c, 12).
func rot12(x, y int32, c, s int64) (int32, int32) {
	u := int64(x)*c - int64(y)*s
	v := int64(x)*s + int64(y)*c
	return int32((u + 2048) >> 12), int32((v + 2048) >> 12)
}

